styles.css:
& > .wp-block-accordion-heading .wp-block-accordion-heading__toggle-icon { font-size: 0; width: var(--wp--preset--spacing--50); height: var(--wp--preset--spacing--50); background-color: var(--wp--preset--color--gris-claro); -webkit-mask: url(/wp-content/uploads/contope-iconos/icono-etmodules-e050.svg) center / contain no-repeat; mask: url(/wp-content/uploads/contope-iconos/icono-etmodules-e050.svg) center / contain no-repeat; transform: none; }
&.is-open > .wp-block-accordion-heading .wp-block-accordion-heading__toggle-icon { display: none; }
&.is-open { background-color: var(--wp--preset--color--fondo-pagina) !important; }
&.is-open > .wp-block-accordion-heading { color: var(--wp--preset--color--dark) !important; }
